# Own-wording magic items of Griffon's Saddlebag, Book 1 (2024), part D: "Shape-Shifter's Circlet" to "Zafu of the Wandering Mind".
# Row shape as tghp_item.py. Weapons and armor use base=[...] with fx atk/dmg/ac for flat bonuses.
ITEMS = []; SP = {}; WPN = {}; GEAR = []; MASTERY = {}; WDESC = {}
def add(name, typ, rar, att, text, **o):
    ITEMS.append((name, typ, rar, att, text, o))

add("Shape-Shifter's Circlet", "Wondrous Item", "Common", 0, "Spend 1 minute massaging your ears, forehead or temples to copy one cosmetic feature of another creature. Pick one: other ears, horns or antlers on your head, or different eyes (color and pupil shape). Only one effect at a time. It ends when you dismiss it as a Bonus Action, remove the circlet or fall Unconscious. You gain no senses or abilities from the copied feature.")
add("Shared Burden", "Wondrous Item", "Rare", 1, "Chained rings and bracers that symbolize a Warlock's pact. They count as a Spellcasting Focus for your Warlock spells. When a Warlock spell damages a creature, you can add your Charisma modifier (min 1) to the damage. If you do, you take Psychic damage equal to half your Charisma modifier (round up), which ignores Resistance and Immunity.", by="a Warlock")
add("Sharkrazor Mantle", "Wondrous Item", "Rare", 1, "A sharkskin cloak that gives you a Swim Speed of 60 ft and lets you breathe underwater. A creature that grapples or Restrains you while touching you takes 1d6 Piercing damage, and again at the start of each of its turns until the condition ends or it stops touching you. You have Advantage on Wisdom (Perception or Survival) checks to find or track a creature missing Hit Points. Your attacks against an Invisible target missing Hit Points do not suffer Disadvantage from that condition.", fx={"swim": 60})
add("Sheer Cold", "Weapon", "Rare", 0, "A Battleaxe with a blade of Everglacier ice. You gain a +1 bonus to attack and damage rolls, and it deals Cold damage instead of Slashing. On a roll of 20 on the attack, choose a 15 ft Cone or a 30 ft long, 5 ft wide Line toward the target. It turns to slick ice for 1 minute and counts as Difficult Terrain. A creature entering it for the first time on a turn or starting its turn there makes a DC 10 Dexterity save or falls Prone. The original target also makes a DC 15 Dexterity save or is Restrained until the start of your next turn, and it can end that with an action and a DC 15 Strength check.", fx={"atk": 1, "dmg": 1}, base=["Battleaxe"])
add("Shield of Yggdrasil", "Armor", "Very Rare", 1, "A massive dwarven tower Shield that needs Strength 17 to wield. It gives +1 AC on top of a normal Shield. **Shield Plant.** As a Bonus Action, plant it in your space for Cover against ranged attacks from your facing. While planted, your Speed is 5 ft and cannot rise, and you reduce Bludgeoning, Piercing and Slashing damage from weapons and Unarmed Strikes by 3. Uproot it as a Utilize action. Doffing it while planting (Magic action) leaves it standing as Cover for others. It falls if you are Unconscious or if a creature within 5 ft knocks it over with a DC 20 Strength (Athletics) check. It has 3 charges and regains all at dawn. Spend 1 charge when planting it, or later as a Bonus Action, to spread metal roots in a 10 ft Emanation that is Difficult Terrain for others but not for you and your allies.", fx={"ac": 3}, base=["Shield"], ch=[3, "all", "dawn"])
add("Shielding Turtle Sugarbombs", "Wondrous Item", "Uncommon", 0, "A pack of two chocolate candies. As a Magic action, eat one to lower your Speed by 10 ft for 1 minute. If you are trained with Shields and carry one on your back, you gain +1 AC for that time. You get no AC bonus if you wield a Shield. **Upset Stomach.** Only one sugarbomb with this property can be active. Eating another ends the first and forces a DC 13 Constitution save, and on a failure you are Poisoned for 1 minute.")
add("Signet Rings of Blindness, Deafness, and Silence", "Ring", "Rare", 0, "Three skull signets, one each for eyes, ears and mouth. Each ring has 1 charge and regains it at dawn. While wearing the matching ring, you can spend its charge (no action) to end the Blinded or Deafened condition, or to speak a word through magical silence. Worn together, the rings pool their charges so one ring's power can be used several times.", ch=[3, "3", "dawn"])
add("Signet Rings of the Fey Court", "Ring", "Very Rare", 1, "Four wooden rings, one per season. You must wear all four to attune. You know Druidcraft and gain Elf's Trance if you lack it. Each ring has 2 charges and regains all on a Long Rest. **Season's Resistance.** As a Reaction when you take the matching damage, spend 1 charge for Resistance to it until your next turn starts, including against the triggering hit. Spring is Radiant, summer Fire, autumn Necrotic, winter Cold. **Magic Resistance.** As a Reaction when an enemy targets you with a spell or magical effect, spend any 2 charges to have Advantage on saves against spells and magical effects until your next turn starts.", by="an Elf or Fey creature", ch=[8, "all", "long"])
add("Silken Socks of Slickening", "Wondrous Item", "Uncommon", 0, "Wear both iridescent socks to cast Grease (save DC 13) centered on a point within 5 ft of you. It works once, then again after the next dawn.", ch=[1, "1", "dawn"])
add("Silver Eagle Weapon", "Weapon", "Uncommon", 0, "A silvered elven Greataxe, Greatsword, Maul or Musket. You gain a +1 bonus to attack and damage rolls, and it deals 2d6 damage on a hit instead of its normal dice. A Critical Hit does not double the dice. Instead, when both damage dice show the same number, roll 1d6 and add it. Keep rolling extra dice while each new roll matches the one before.", fx={"atk": 1, "dmg": 1})
add("Silver Lycan Chime", "Wondrous Item", "Uncommon", 0, "A small silver bell steeped in Divination magic, strongest under a full moon. When hung, it rings a melody if a Lycanthrope passes within 15 ft, or within 60 ft during a full moon. It is quiet but audible out to 100 ft, and each kind of Lycanthrope has its own melody.")
add("Singing Stein", "Wondrous Item", "Common", 0, "A pewter stein with a face that sings when it holds at least a sip of potable alcohol. The song fits the drink: wine gives a ballad, rum a sea shanty, ale a drinking song. Mixed drinks make it alternate or blend lyrics. Several steins with the same drink sing in harmony. Poisoned drink makes it sing slightly off key, and a Search action with a successful Wisdom (Perception) check (DC set by the GM) notices it.")
add("Sirensong Silencer", "Wondrous Item", "Uncommon", 0, "A golden ear cuff you put on as a Magic action. You have Advantage on saves to avoid or end the Charmed condition. Tapping it twice (no action) makes you Deafened, though you still faintly hear the sea. Tapping twice again ends it.")
add("Sling of the Tiny Giant", "Weapon", "Rare", 1, "A Sling that is deadly against larger foes. You gain a +1 bonus to attack and damage rolls. A ranged hit deals an extra 1d4 Force damage per size category the target is larger than you, up to 3d4. On a roll of 20 on the attack, the target makes a DC 15 Strength save or is pushed 10 ft away and knocked Prone. A Large or larger target has Disadvantage on that save.", fx={"atk": 1, "dmg": 1}, base=["Sling"])
add("Smash Potatoes", "Wondrous Item", "Common", 0, "Fist-shaped potatoes grown by war clerics. Eating one makes your hands itch for 1 hour. For that time, your Unarmed Strike with a hand can deal 1d4 instead of its normal damage. Each extra potato adds 1 hour. You can eat up to three before a Long Rest.")
add("Snuff", "Weapon", "Very Rare", 1, "A dark Sickle with a harsh angle and power over light. You gain a +1 bonus to attack and damage rolls, and it deals an extra 1d6 Psychic damage. As a Magic action with a command word, extinguish all nonmagical flames within 60 ft and dispel spell-made Bright or Dim Light within 60 ft as Dispel Magic (+4 modifier). Once used, it needs the next dusk. As a Magic action, extend the handle into a scythe wreathed in shadow with the Two-Handed and Reach properties and extra Psychic damage of 2d6. A Bonus Action returns it to Sickle form.", fx={"atk": 1, "dmg": 1}, base=["Sickle"], ch=[1, "1", "dusk"])
add("Snugglebeast (Dragon)", "Wondrous Item", "Rare", 0, "An enchanted toy. A creature that spends a Short Rest snuggling it and also spends Hit Point Dice at the end of that rest regains an extra 3d6 Hit Points. Only one Snugglebeast helps a creature at a time. After use, that creature cannot benefit from the same toy until it finishes a Long Rest.")
add("Snugglebeast (Owlbear)", "Wondrous Item", "Common", 0, "An enchanted toy. A creature that spends a Short Rest snuggling it and also spends Hit Point Dice at the end of that rest regains an extra 1d6 Hit Points. Only one Snugglebeast helps a creature at a time. After use, that creature cannot benefit from the same toy until it finishes a Long Rest.")
add("Snugglebeast (Tarrasque)", "Wondrous Item", "Very Rare", 0, "An enchanted toy. A creature that spends a Short Rest snuggling it and also spends Hit Point Dice at the end of that rest regains an extra 4d6 Hit Points. Only one Snugglebeast helps a creature at a time. After use, that creature cannot benefit from the same toy until it finishes a Long Rest.")
add("Snugglebeast (Unicorn)", "Wondrous Item", "Uncommon", 0, "An enchanted toy. A creature that spends a Short Rest snuggling it and also spends Hit Point Dice at the end of that rest regains an extra 2d6 Hit Points. Only one Snugglebeast helps a creature at a time. After use, that creature cannot benefit from the same toy until it finishes a Long Rest.")
add("Snugglebeasts", "Wondrous Item", "Unknown", 0, "A family of enchanted toys in four forms: Owlbear (Common, extra 1d6 Hit Points), Unicorn (Uncommon, 2d6), Dragon (Rare, 3d6) and Tarrasque (Very Rare, 4d6). See each entry for the rules.")
add("Socks of the Well-Rested", "Wondrous Item", "Uncommon", 0, "Wear both socks when you finish a Long Rest to gain Temporary Hit Points equal to 1d8 plus your Constitution modifier.")
add("Spellwoven Robe", "Wondrous Item", "Uncommon", 0, "A robe of magic-sensitive thread that shows glyphs when you cast. While you wear it and no armor, your base AC is 10 plus your spellcasting ability modifier. When you cast a level 1+ spell in it, you can change its look, color and material. It stays a robe of the same weight.")
add("Spiderbite Daggers", "Weapon", "Rare", 0, "A pair of Daggers made from the fangs of a large venomous spider. When you hit the same creature with both on your turn, it makes a DC 13 Constitution save or takes an extra 2d4 Poison damage and is Poisoned until the end of its next turn.", base=["Dagger"])
add("Spire Seed", "Wondrous Item", "Legendary", 1, "A 1 ft long seed in a protective cone. Plant it while attuned and it becomes a 300 ft tall, 40 ft wide tree in 30 days. Only you can then attune to it, and your attunement survives distance and your death (for up to 1 minute dead) but ends if you are on another plane for 24 hours. If it ends before the tree is grown, the tree dies. A loyal Dryad guards the door with the key stem, and once she opens it the tree is yours. Inside are ten floors you lay out, hidden from Divination and teleportation. The tree has AC 20, HP 500, Immunity to Poison, Psychic and nonmagical weapon damage (except siege equipment) and Resistance to the rest. The door has AC 15, HP 100. The tree regains 1d6 HP at dawn, and lost parts regrow in 7 days. If attacked, it calls a Treant once per day until dawn. Neither creature strays over 1 mile. If the dryad is killed, the tree loses its magic. It makes a new Spire Seed every 100 years.")
add("Spirit Pike", "Weapon", "Rare", 1, "A Pike that you can use with proficiency even if you lack it. When you cast Spiritual Weapon while holding it, the Pike can dissolve and become the spectral weapon. Its hit deals Force damage of 1d10 plus your spellcasting modifier, and the spell's higher-slot scaling stays 1d8 per level. The Pike returns when the spell ends. It has 4 charges and regains all at dawn. When you hit with it, in either form, spend 1 charge for an extra 1d8 Radiant damage.", base=["Pike"], by="a Cleric", ch=[4, "all", "dawn"])
add("Splintershot", "Weapon", "Rare", 0, "A Shortbow that shatters an Arrow into magical shrapnel. As a Magic action with a command word, destroy one nonmagical nocked Arrow. Each creature in a 15 ft Cone makes a DC 15 Dexterity save and takes 2d6 Piercing damage on a failure, or 3d6 if within 5 ft of you.", base=["Shortbow"])
add("Splitter", "Weapon", "Very Rare", 1, "A Halberd with a hatchet-like blade. While holding it with two hands, use a Bonus Action and a command word to split it into a Handaxe and a Quarterstaff, each with the Light property. Repeat to rejoin them. You gain +3 to attack and damage rolls with the Halberd, or +1 with each part when split. **Halberd.** When you roll a 10 on the damage die, the target's Speed drops by 10 ft until your next turn starts and yours rises by 10 ft. **Handaxe and Quarterstaff.** Wielded in separate hands, you gain +1 AC and add your ability modifier to the Light-property bonus attack if it is not already added. The Quarterstaff deals Necrotic damage and maximum damage to plants. The Handaxe returns to your hand right after a ranged attack.", fx={"atk": 3, "dmg": 3, "ac": 1}, base=["Halberd"])
add("Squasher", "Weapon", "Uncommon", 0, "A big, tough squash that works as a magic weapon. A Druid wielding it can use Wisdom instead of Strength for its melee attack and damage rolls.", base=["Greatclub"])
add("Staff of Favorable Winds", "Staff", "Very Rare", 1, "Wind-caused Difficult Terrain costs you no extra movement. The staff has 10 charges and regains 1d6 + 4 at dawn. Spend charges to cast, using your spell save DC: Cone of Cold (5), Feather Fall (1), Gust of Wind (2) or Wind Wall (3). As a Magic action, create a harmless sensory effect with air, such as rustling leaves or billowing clothes. If you spend the last charge, roll 1d20. On a 1, the staff turns to dust.", base=["Quarterstaff"], by="a Druid, Sorcerer, Warlock or Wizard", ch=[10, "1d6+4", "dawn"])
add("Staff of the Four Seasons", "Staff", "Very Rare", 1, "A Quarterstaff with +2 to attack and damage rolls that changes with the seasons. It has 10 charges and regains 1d6 + 2 at dawn. While it has a charge, melee hits deal an extra 1d8 damage of the season's type: spring Radiant, summer Fire, autumn Necrotic, winter Cold. Spend 10 minutes to change the season for 8 hours. Spend charges to cast, using your spell save DC and attack modifier. **Spring.** Guiding Bolt (1), Moonbeam (2), Plant Growth (3). **Summer.** Burning Hands (1), Spike Growth (2), Fireball (3). **Autumn.** Inflict Wounds (1), Pass Without Trace (2), Vampiric Touch (3). **Winter.** Color Spray (1), Darkvision (2), Sleet Storm (3). If you spend the last charge, roll 1d20. On a 1, it becomes a nonmagical Quarterstaff.", fx={"atk": 2, "dmg": 2}, base=["Quarterstaff"], by="a Druid, Sorcerer, Warlock or Wizard", ch=[10, "1d6+2", "dawn"])
add("Staff of the Magpie", "Staff", "Rare", 1, "A 10 lb stone staff topped with a magpie bust. Holding it gives +1 to Wisdom (Perception) checks to find treasure or a specific item. It has 10 charges and regains 1d6 + 4 at dawn. Spend charges to cast Fly (3) or Locate Object (2). If you spend the last charge, roll 1d20. On a 1, the magpie comes alive and flies off, leaving a nonmagical Quarterstaff.", base=["Quarterstaff"], by="a spellcaster", ch=[10, "1d6+4", "dawn"])
add("Staff of the Mirage", "Staff", "Rare", 1, "It has 10 charges and regains 1d6 + 4 at dawn. Spend charges to cast, using your spell save DC with a +2 bonus: Disguise Self (1), Hallucinatory Terrain (4), Invisibility (2), Mirror Image (2), Mislead (5) or Silent Image (1). If you spend the last charge, roll 1d20. On a 1, the staff vanishes.", base=["Quarterstaff"], by="a Wizard", ch=[10, "1d6+4", "dawn"])
add("Staff of the Mustang", "Staff", "Rare", 1, "A dark wooden staff carved as a stallion. It has 10 charges and regains 1d6 + 4 at dawn. Spend 1 charge to cast Phantom Steed. Spend 1 charge and a command word to Dash as a Bonus Action. If you spend the last charge, roll 1d20. On a 1, it snaps in two and is destroyed, and galloping hooves fade into the distance.", base=["Quarterstaff"], ch=[10, "1d6+4", "dawn"])
add("Staff of the Reverent Warrior", "Staff", "Rare", 1, "A Quarterstaff with +2 to attack and damage rolls, adorned with blades. Even unattuned, its attacks can deal Bludgeoning, Piercing or Slashing damage (your choice). It has 10 charges. While attuned you know True Strike, and when you cast it holding the staff you can spend charges to boost it. Spend 2 for a Bonus Action cast. Spend 1 to give the next attack roll against the target Advantage until the end of your next turn. On a hit, spend 1 for an extra 1d6 Radiant damage. It regains 1d6 + 4 at dawn. If you spend the last charge, roll 1d20. On a 1, it becomes a nonmagical Quarterstaff that still chooses its damage type.", fx={"atk": 2, "dmg": 2}, base=["Quarterstaff"], by="a spellcaster", ch=[10, "1d6+4", "dawn"])
add("Stalaga Spear", "Weapon", "Very Rare", 1, "A granite Spear with a ruby head that weighs as a normal Spear. You gain a +1 bonus to attack and damage rolls. It has 4 charges and regains 1d4 at dawn. Within 5 ft of unworked stone or earth, spend a Magic action and 1 charge to plunge it in. It erupts as a 1 ft wide, 10 ft long spike from another such surface within 60 ft you can see. Creatures in the 5 ft wide, 10 ft long Line make a DC 16 Dexterity save, taking 4d6 Piercing damage and being pushed 5 ft on a failure, or half damage on a success. Within 60 ft of the spike and 5 ft of stone or earth, recall the Spear as a Bonus Action with a command word.", fx={"atk": 1, "dmg": 1}, base=["Spear"], ch=[4, "1d4", "dawn"])
add("Starbreaker", "Weapon", "Rare", 1, "A glowing Morningstar that sheds Bright Light in a 20 ft radius and Dim Light for 20 ft more. You gain a +2 bonus to attack and damage rolls, and it deals an extra 1d4 Radiant damage. You can cast Daylight with it once per dawn.", fx={"atk": 2, "dmg": 2}, base=["Morningstar"], ch=[1, "1", "dawn"])
add("Starmetal Ring", "Ring", "Rare", 0, "A rough ring with a pull on metal. Spend 1 hour touching an object (up to 25 lb, at least half metal) to bind it to the ring, one at a time. While wearing the ring, use a Bonus Action to pull the bound object up to 20 ft toward you if it is within 40 ft and not behind Cover. It bounces off creatures and objects on the way. If it reaches your space, you can catch it with a free hand or it drops at your feet.")
add("Starmetal Shield", "Armor", "Legendary", 1, "An open metal Shield that floats above its paired gauntlet. While wearing the gauntlet, you count as wielding the Shield but get +1 AC instead of the normal Shield bonus. The bonus is +3 against attacks made with a metal weapon or projectile. **Shooting Star.** As a Magic action, throw it at up to three creatures, objects or points. The first must be within 30 ft, and each next within 10 ft of the one before, with no repeats. Make a ranged attack against each, ignoring Cover. You are proficient and add Strength or Dexterity to attack and damage. A hit deals 2d8 Slashing damage. It returns to the gauntlet after the last target.", fx={"ac": 1}, base=["Shield"])
add("Starmetal Solar Axe", "Weapon", "Legendary", 1, "An axe forged from star iron that is either one Greataxe (fused) or two Battleaxes (fissioned). **Fused.** +1 to attack and damage, an extra 2d6 Fire damage, and flames shed Bright Light in a 20 ft radius and Dim Light for 20 ft more, as sunlight. **Fissioned.** Each Battleaxe has +1 and an extra 1d6 Cold damage. They orbit you and count as sheathed. When you take the Attack action, a Bonus Action lets an orbiting axe attack a target within 20 ft. **Fission.** With a Bonus Action and a command word, split the Greataxe. Others within 30 ft make a DC 17 Dexterity save and take 3d6 Lightning damage, or half on a success. **Fusion.** With both axes held, a Bonus Action and another command word rejoin them. Others within 30 ft make a DC 17 Dexterity save and take 3d6 Fire damage, or half on a success. Each of these can be used only once per 12 hours.", fx={"atk": 1, "dmg": 1}, base=["Greataxe"])
add("Starmetal Striker", "Weapon", "Rare", 1, "A Light Hammer forged from a comet, cold to the touch. You gain a +2 bonus to attack and damage rolls, and it deals an extra 1d4 Cold damage. After a thrown attack it flies back to your hand, leaving a crackling mist.", fx={"atk": 2, "dmg": 2}, base=["Light Hammer"])
add("Steps of the Trickster", "Wondrous Item", "Common", 0, "Shoes that let you change the sound of your steps, though not the volume. You can make them sound like any material, such as bare feet, dancing heels or a guard's metal boots.")
add("Storm Sickle", "Weapon", "Rare", 0, "A Sickle that sparks and drips with water. Attacks deal an extra 1d4 Lightning damage. You can also slash the air to send a wind blade. You are proficient with it, the range is 20/60 ft, it uses Strength and deals 1d4 Slashing damage, and it gets the extra Lightning damage too.", base=["Sickle"])
add("Storm Thrower Harpoon", "Weapon", "Legendary", 1, "A Trident with a +3 bonus to attack and damage rolls. Thrown, it deals an extra 1d8 Lightning damage. After a throw, hit or miss, pull it back with its chain as a Bonus Action. After hitting a creature with it under open sky, call lightning. The target and each creature within 5 ft make a DC 16 Dexterity save and take 6d10 Lightning damage on a failure, or half on a success. Those in water or metal armor have Disadvantage, and you are immune to this lightning. Usable once until the next dawn. **Impale.** As a Magic action, make a ranged attack with it at a target no more than one size larger than you. On a hit, the target makes a DC 17 Strength save or is pulled up to 20 ft toward you.", fx={"atk": 3, "dmg": 3}, base=["Trident"], ch=[1, "1", "dawn"])
add("Stormstruck Staff", "Weapon", "Rare", 0, "A lightning-scarred Quarterstaff with a crystal at its head. You gain a +1 bonus to attack and damage rolls, and it deals an extra 1 Lightning damage. When the staff takes Lightning damage, or you do while holding it (from another source), the crystal glows for 1 minute. It also glows under Shillelagh. While glowing it sheds Bright Light in a 10 ft radius and Dim Light for 10 ft more, and the extra Lightning damage becomes 1d6.", fx={"atk": 1, "dmg": 1}, base=["Quarterstaff"])
add("Sundersludge Net", "Wondrous Item", "Uncommon", 1, "A Net made from a gray ooze. A creature Restrained by it takes 1d6 Acid damage when it gains the condition and at the end of each of its turns until freed. Nonmagical metal armor it wears takes a cumulative -1 AC penalty with each Acid hit and is destroyed when the AC would reach 10. Mending removes the penalty. Another creature that touches the Net takes 1d6 Acid damage. To escape, the target or an ally within 5 ft uses an action for a DC 13 Strength (Athletics) check. The Net (AC 10, 5 HP, Immunity to Bludgeoning, Poison and Psychic, Resistance to all other damage) frees the target if destroyed and is then harmless. If over half is saved and soaked in 5 gallons of liquid for 12 hours, it is repaired. Attunement ends if it stays torn over 48 hours. You are immune to its damage. A thrown Net is harmless until thrown again, and it does no Acid damage if nobody is attuned to it.")
add("Switch", "Rod", "Very Rare", 1, "A springy rod of vines. While holding it, spend a use of Wild Shape as a Bonus Action to turn it into any Simple or Martial weapon of your choice that deals Bludgeoning or Piercing damage and lacks Loading and Reach. A weapon with Ammunition makes its own. You are proficient with it and can use Wisdom for attack and damage. It deals an extra 1d8 damage of its type. A Bonus Action changes its form or returns it to a rod. Spend a second use of Wild Shape as a Magic action to cover yourself in bark. You gain Temporary Hit Points equal to four times your Druid level, and your AC is 17 if lower. It ends after hours equal to half your Druid level (round down), at 0 Hit Points, or early as a Bonus Action.", by="a Druid")
add("Sword of Resonance", "Weapon", "Rare", 1, "A brass Longsword with lute strings. It works as a Musical Instrument and a Spellcasting Focus, and you are proficient with it as both. You gain +2 to attack and damage rolls, and it has the Finesse property. When you spend Bardic Inspiration while holding it, it rings with thunder. Your next hit with it before the end of your next turn deals an extra 1d6 Thunder damage.", fx={"atk": 2, "dmg": 2}, base=["Longsword"], by="a Bard")
add("Sword of the Spelldrinker", "Weapon", "Legendary", 1, "A Longsword that drinks light. You gain a +3 bonus to attack and damage rolls. Magical light and Darkness within 30 ft count as nonmagical, and you can breathe in any environment. It has 2 charges and regains 1d2 at dusk. Spend 1 to cast Counterspell. The target automatically fails if the spell is level 5 or lower and automatically succeeds against level 6+. When it works, you can absorb the spell instead (casting time of an action or Bonus Action), one at a time for 8 hours, replacing the old one. You can release it with a Magic action or Bonus Action to match its casting time, using the original caster's slot level, DC, attack bonus and ability.", fx={"atk": 3, "dmg": 3}, base=["Longsword"], ch=[2, "1d2", "dusk"])
add("Talyard the Great's Wand of Power", "Wand", "Uncommon", 0, "A spruce stick that looks like a magnificent wand to anyone drunk who sees it. It has 3 charges and regains 1d3 at dusk. While you are drunk and holding it, spend charges to cast (+3 spellcasting modifier): Heroism (1), Lesser Restoration (2) or Thaumaturgy (0).", ch=[3, "1d3", "dusk"])
add("Tear of Gaia", "Wondrous Item", "Common", 0, "A small green gem. Crush it underfoot as a Magic action. Plants in a 10 ft Emanation from you become healthy and full, and fruit and vegetable plants bear produce that ripens over 1 hour. With no plants in range, or if crushed on inorganic ground, the area gets 1 inch of fertile topsoil and green grass.")
add("Tectonic Gauntlets", "Wondrous Item", "Artifact", 1, "Stone gauntlets with Earth's power. Your fist Unarmed Strikes deal 1d8 Bludgeoning damage (unless already higher) and double damage to objects and structures. They have 15 charges and regain 1d10 + 5 at dawn. On a fist Unarmed Strike, spend up to 5 charges to add 5 ft of reach per charge. **Powerglove.** On a hit, spend up to 3 charges for an extra 1d8 Bludgeoning damage each. If you spend any, the target makes a DC 18 Strength save or is pushed 5 ft. **Geomancy.** Cast with save DC 18: Earthquake (8), Move Earth (6), Shatter (2), Spike Growth (2, stone projections) or Wall of Stone (5). **Tectonic Plate Armor.** As a Magic action, for 1 hour you have Resistance to Bludgeoning, Piercing and Slashing, half Speed, and Disadvantage on Dexterity checks and saves. A Bonus Action ends it. You gain a 30 ft Burrow Speed through nonmagical, unworked earth and stone without disturbing it. If it ends while you are burrowed, you are shunted to the nearest free space and take 1d10 Force damage. Usable again after a Short or Long Rest. **Curse.** The gauntlets fuse to your flesh and cannot be removed. Your Speed drops by 5 ft and your Intelligence drops by 4 (minimum 7). The curse stays after attunement ends until Greater Restoration, Remove Curse or similar magic. **Random Properties.** One minor beneficial and one minor detrimental artifact property. **Destruction.** Only in the crystalline mines of Durhun on the Elemental Plane of Earth.", ch=[15, "1d10+5", "dawn"])
add("Telescoping Bladelance", "Weapon", "Uncommon", 0, "A mechanical weapon you extend or retract with a Bonus Action by twisting the handle. Extended, it is a Lance. Retracted, it is a Greatsword that deals 1d10 Slashing damage instead of 2d6. While it is a Greatsword, you can extend it as a Bonus Action right after hitting. A Large or smaller target is then pushed 5 ft away.", base=["Lance"])
add("Tempest Griffon Feather Cape", "Wondrous Item", "Very Rare", 1, "A cape that gives you Resistance to Lightning damage and Advantage on Dexterity saves against Lightning effects. As a Magic action with a command word, become a bolt of lightning and travel to an unoccupied space you can see within 120 ft without provoking Opportunity Attacks, filling a 5 ft wide Line along the path. Others in the Line, or within 5 ft of your old or new space, make a DC 16 Dexterity save and take 3d10 Lightning damage on a failure, or half on a success. Usable again after the next dawn.", fx={"res": ["Lightning"]}, ch=[1, "1", "dawn"])
add("Tether Tearer", "Weapon", "Uncommon", 0, "A silver axe that pins a spirit to the material world. When you hit a creature with Incorporeal Movement, it takes an extra 1d6 Force damage and cannot use that trait until the end of its next turn.")
add("Tethervine Quiver", "Wondrous Item", "Uncommon", 0, "An overgrown Quiver for up to 20 Arrows or Bolts that hides a plant. When you draw ammunition, use a Bonus Action and a command word to tie it to the vine. The vine trails the shot and becomes taut and climbable (holds 250 lb) if it hits a surface. While wearing the Quiver, retract the vine and its ammunition up to 60 ft as a Bonus Action. An object under 25 lb it hit comes along. If the ammunition hits a creature, the vine lets go and falls. A Bonus Action and the command word, or cutting it, also releases it. The vine reaches 120 ft, and the shot cannot go farther. A severed part regrows up to 30 ft each dawn, and the cut piece becomes mundane Rope.")
add("The Griffon's Saddlebag", "Wondrous Item", "Artifact", 0, "A leather bag with a griffon's face, made by the six-armed astral griffon Criir. It is usually found by an adventurer with a destiny. **Superior Holding.** Always 3 lb, it works as a Bag of Holding that only another Artifact can pierce. Placing a Bag of Holding, Heward's Handy Haversack, Portable Hole or similar item inside it, or the reverse, destroys the other item and moves its contents into the saddlebag. If that overloads it, random contents scatter in the Astral Plane. **Magic Courier.** At the GM's discretion, the beak opens to show a letter. Any creature with Intelligence 4+ can read it. It names an item and a person or place, with a price and a deadline. If brought in time, it hands over the item. If payment is not made within 1 hour, the item vanishes. After payment it gives the courier a reward. **Sell Magic Items.** Sell a magic item to it for half its base price. **Spells.** 8 charges, regains 1d6 + 2 at dawn. While wearing it, cast Detect Magic (1), Identify (1) or Legend Lore (5). The GM may unlock more: Blink (3), Dimension Door (4), Divination (4), Etherealness (7), Fly (3), Mordenkainen's Magnificent Mansion (7), Plane Shift (7) or Leomund's Secret Chest (4). **Sentience.** Chaotic Neutral, Int 13, Wis 15, Cha 16. Hearing and normal vision to 60 ft. It knows Common and speaks aloud among trusted creatures, otherwise telepathically with its wearer. It can talk with griffons. It likes to carry, collect and deliver magic items, and failed courier quests may make it withhold its magic, and items may be locked inside or spat out. **Destruction.** Piercing it with an Artifact sends it to its origin for repair, and it returns elsewhere. Putting one inside another sends both home and their contents to Criir's forge.", ch=[8, "1d6+2", "dawn"])
add("The Rose Basket", "Weapon", "Very Rare", 1, "A silver Rapier with a rose on its guard and thorns on its hilt. You gain a +2 bonus to attack and damage rolls. Against a Fey or a shape-shifted creature it deals an extra 1d8 Radiant damage. **Field of Roses.** As a Magic action with a command word, touch the point to the ground to raise silver rosebushes in a 25 ft square centered on you. It is Difficult Terrain for 1 minute or until you dismiss it as a Bonus Action. A creature takes 2d4 Piercing damage per 5 ft it moves in the area. You ignore the cost and the damage while holding the Rapier. Usable again after the next dawn.", fx={"atk": 2, "dmg": 2}, base=["Rapier"], ch=[1, "1", "dawn"])
add("Thornpiercer", "Weapon", "Legendary", 1, "A rose with a stem you can hold as a hilt. As a Bonus Action, grow a Dagger, Shortsword, Rapier or Whip from its center. A new one replaces and withers the old. You gain a +2 bonus to attack and damage rolls, an extra 1d4 Piercing damage on a hit, and proficiency with the grown weapons. **Dagger.** A thrown blade bursts into thorns on hit or miss. The target and up to three creatures of your choice within 10 ft make a DC 17 Dexterity save or take 1d4 + 2 Piercing damage. **Rapier.** On a roll of 20, the target takes an extra 10 Piercing damage. If it is Large or smaller, it makes a DC 17 Constitution save. On a failure its Hit Point maximum drops by the damage it took from the attack, and on a success by half that. This returns after a Short or Long Rest. **Shortsword.** The first creature you hit each turn makes a DC 17 Constitution save or takes 1d6 Poison damage and is Poisoned until the end of its next turn. **Whip.** When you hit a Medium or smaller creature, you can try to grapple it. It makes a DC 17 Strength save or is Grappled and takes 1d4 Piercing damage at the start of each of its turns. It or an ally within 5 ft can free it with an action and a DC 17 Strength (Athletics) check. The Whip breaks off from the hilt on a grapple so you can move freely.", fx={"atk": 2, "dmg": 2})
add("Thunderous Flail", "Weapon", "Rare", 1, "A Flail with 3 charges that regains 1d3 at dawn. With at least 1 charge, the first target you hit each turn takes an extra 1d6 Lightning damage. Spend 1 charge to cast Thunderwave (save DC 15) from its ball, or as a Bonus Action right after a melee hit toward that target. The ball can be released mid-swing for a ranged attack. You are proficient, the range is 20/60 ft, it uses Strength and deals 1d8 Bludgeoning damage. While it is within 60 ft, pull it up to 20 ft toward you as a Bonus Action. It bounces off creatures and objects in the way, and reattaches when it enters your space. While detached, Thunderwave starts from the ball and fills a 10 ft radius Sphere centered on it.", base=["Flail"], ch=[3, "1d3", "dawn"])
add("Thwackstaff", "Weapon", "Uncommon", 1, "A festive Quarterstaff with ribbons that has the Finesse property. You get +1 to Charisma (Performance) checks to entertain with it. It has 3 charges and regains all at dawn. **Punishing Parry.** As a Reaction when a creature you see hits you with a melee attack, spend 1 charge and roll 1d6. Add it to your AC against that attack. If the attack misses, you can attack the attacker with the staff as part of the Reaction, and a hit deals extra damage equal to the number rolled.", base=["Quarterstaff"], ch=[3, "all", "dawn"])
add("Timber", "Weapon", "Very Rare", 1, "A Handaxe whose power builds with each strike. Its bonus to attack and damage rolls equals its current charges. It gains 1 charge on each hit, up to 3. On the third, the energy explodes, charges reset, and the target takes an extra 3d6 Force damage, or 6d6 if made of wood. You can also push a target up to one size larger than you 10 ft. Charges last up to 1 minute and are lost if you miss, attack a different target, or attack with another weapon.", base=["Handaxe"])
add("Timepiercer", "Weapon", "Very Rare", 1, "A quartz sword hilt holding an hourglass whose sand never spills. As a Bonus Action with a command word, the sand forms a Rapier blade. A Bonus Action and the command word return it. While formed, you gain +2 to attack and damage rolls. While holding the hilt, cast Haste or Slow (save DC 16) from it, with Advantage on Constitution saves to keep Concentration on it. You can use each spell once until the next dawn. The sand speeds up with Haste and slows with Slow.", fx={"atk": 2, "dmg": 2}, base=["Rapier"], ch=[2, "2", "dawn"])
add("Timeshifter's Mantle", "Wondrous Item", "Rare", 0, "A cloak that bends time. When a Large or smaller creature hits you with a melee attack, take a Reaction. After the damage, move up to half your Speed without provoking Opportunity Attacks, and the attacker's Speed becomes 0 until the start of its next turn. Usable again after the next dawn.", ch=[1, "1", "dawn"])
add("Toadstone", "Wondrous Item", "Uncommon", 1, "A jade frog on a leather cord. You gain a Swim Speed equal to your Speed and can hold your breath for 1 hour. You can cast Jump on yourself once until the next dusk. **Curse.** Attuning curses you until Remove Curse or similar magic, and removing it does not help. Your skin stays damp and clammy, and you crave only insects and grubs.", fx={"swim": "walk"}, ch=[1, "1", "dusk"])
add("Tome of Dreams", "Wondrous Item", "Uncommon", 0, "A book of gripping short stories. Read one in 10 minutes. After your next Long Rest, roll 1d20. On 10 or lower, you take 2d4 Psychic damage from terrors. On 11 or higher, you gain 2d4 Temporary Hit Points. An unfinished story has no effect.")
add("Torchbearer's Reach", "Weapon", "Uncommon", 0, "A weapon with a magic flame on its handle that sheds Bright Light in a 20 ft radius and Dim Light for 20 ft more. Snap the handle (no action) to extend the flame into a 10 ft coil used as a Whip. It has the Light property and deals Fire damage instead of Slashing. The flame does not hurt you and cannot bind creatures or fetch objects, but it lights fires. A Bonus Action snuffs it.", base=["Whip"])
add("Torpedo Ammunition", "Weapon", "Common", 0, "Spiral-shaped Arrows or Bolts. Fired underwater, they ignore the usual underwater combat penalties. Fired anywhere else, their normal and long range are halved.")
add("Torrent Taiaha", "Weapon", "Rare", 0, "A wooden staff circled by a mote of water, wielded as a Quarterstaff. You gain a +1 bonus to attack and damage rolls. You can lash out with the water for a special melee attack. You are proficient with it, the reach is 10 ft, you can use Wisdom for attack and damage, and it deals 1d4 Bludgeoning damage. The +1 applies to both forms. While holding it, you can walk on liquid as if solid, and you sink normally if you end your turn there. You can cast Control Water (only flood or part water) from it once until the next dawn, and it ends early if you let go.", fx={"atk": 1, "dmg": 1}, base=["Quarterstaff"], ch=[1, "1", "dawn"])
add("Tote of Tricky Treat Sugarbombs", "Wondrous Item", "Common", 0, "A canvas bag holding 5d8 + 10 clove and pumpkin candies, with an illusory face on its pumpkin at night. Eat one as a Magic action and roll d20 for a minor effect that lasts 1 minute unless noted. 1: DC 13 Constitution save or lose your next action retching. 2: your face looks melted and skull-like (illusion). 3: food and water taste like ash and blood. 4: others' eyes look hollow and black. 5: your ears change color each turn. 6: your hair falls out and regrows. 7: maniacal laughter. 8: snake pupils. 9: an unseen fly buzzes. 10: orange skin, Bright Light 10 ft and Dim Light 10 ft more from eyes and mouth. 11: confetti and children's laughter. 12: tiny flightless bat wings. 13: you know the nearest pumpkin within 1 mile. 14: crows and ravens land on you. 15: a floppy wizard hat appears and fades in stars. 16: alcohol becomes nonalcoholic. 17: a golden voice, adding Proficiency to Charisma (Performance) to sing, or Expertise if already proficient. 18: food and water taste delicious. 19: Darkvision 30 ft, or +30 ft if you have it. 20: you sense possession and see Invisible creatures.")
add("Trident of the Dryad", "Weapon", "Uncommon", 1, "A wooden Trident with 4 charges that regains 1d3 + 1 at dawn. Within 5 ft of a Large or bigger tree, spend a Bonus Action and 1 charge to teleport to a space within 5 ft of another such tree within 60 ft. **Tree Form.** As a Magic action with a command word, plant the base in fertile ground to turn it into a 60 ft tall tree with a 5 ft wide trunk and a 20 ft Emanation canopy. Within 5 ft of it, spend a Bonus Action and 1 charge to teleport to another point on its trunk or branches. It shows faint Transmutation to Detect Magic. Touch it and repeat the command word as a Magic action to revert, and creatures in it fall. Usable again after the next dawn.", base=["Trident"], ch=[4, "1d3+1", "dawn"])
add("Trident of the Hydra", "Weapon", "Rare", 0, "A mithral Trident with a short handle that lacks the Versatile property. You gain a +1 bonus to attack and damage rolls. When you throw it, it splits into three spears and you make three ranged attacks instead of one. Each deals 1d6 Piercing damage and gets no ability modifier unless it is negative. Afterward it regrows its prongs from one spear and the other two dissolve.", fx={"atk": 1, "dmg": 1}, base=["Trident"])
add("Tub of Churning and Fermentation", "Wondrous Item", "Uncommon", 0, "A tub holding 2 gallons of liquid or 1 cubic foot of material. Put in a liquid or perishable, close the lid and name an end product it can make. After 10 minutes it clicks open with the result. Examples: apples to hard cider, fruits to wine, cabbage to sauerkraut, cucumbers and vinegar to pickles, milk to butter, cheese or yogurt. Extra ingredients change the flavor. Usable again after the next dawn.", ch=[1, "1", "dawn"])
add("Uorik the Conqueror's Juice Cup", "Wondrous Item", "Common", 0, "A brass cup. As a Bonus Action, whisper a fruit's name into it to give the water inside that fruit's juice color and flavor. Saying another fruit changes it again. It is still just water. Shouting into the cup makes it fizz. Poisoned water tastes foul and badly fermented.")
add("Vancian Helm", "Wondrous Item", "Rare", 1, "A helmet made from a shield guardian's remains. You gain +1 AC while wearing it. **Spell Storing.** Any creature can store a spell of level 1 to 4 by touching the helm as the spell is cast. It holds one spell at a time. While wearing it, you can cast that spell using the original caster's slot level, DC, attack bonus and ability, and the spell is then lost, as it is when a new one is stored. A level 5+ spell cast into it while worn is lost, the slot is spent, and you take 2d6 Psychic damage. Your eyes glow in a color of your choice while a spell is stored.", fx={"ac": 1})
add("Venombane Armor", "Armor", "Uncommon", 1, "Any Light armor (or mixed). It absorbs poison and eases webs. You cannot be caught in webs and you move through them as Difficult Terrain. When you take Poison damage, use a Reaction to reduce it by 1d8 plus your Constitution modifier.")
add("Vigilus", "Weapon", "Rare", 1, "A Hand Crossbow with a spring case for six Bolts that loads itself, so you ignore its Loading property while the case has Bolts. A Utilize action reloads the case. As a Magic action, unfold three legs and plant it in your space as a Tiny turret. Within 30 ft of it, command it as a Bonus Action to attack a target you see within 30 ft of it, using your ability modifier. It draws and loads the next Bolt itself. The first creature that is Invisible (not you) to enter a space within 30 ft of it makes it chirp audibly out to 100 ft. It is an object with AC 12, HP 30 and Immunity to Poison and Psychic. At 0 HP it falls and cannot deploy for 1 minute. Retrieve it as a Bonus Action from its space.", base=["Hand Crossbow"])
add("Visage of Delight and Disaster", "Wondrous Item", "Legendary", 1, "A mask that mirrors your expression. You gain two d10 Bardic Inspiration dice that work as the level 1 Bard feature and add to any you already have. You regain them after a Short or Long Rest. **Delight.** Given with a joyful performance, the creature has Advantage on saves to avoid or end Frightened for 1 minute. When it uses the die, it gains Temporary Hit Points equal to twice the roll. **Disaster.** Given with a grim performance, the creature has Advantage on saves to avoid or end Charmed for 1 minute. When it hits with a weapon or Unarmed Strike, it can spend the die to deal extra Psychic damage equal to twice the roll.", by="a creature with Charisma 17 or higher")
add("Void Ammunition", "Weapon", "Uncommon", 0, "Ammunition made of packed shadow. It deals Psychic damage instead of Piercing. It makes no sound, leaves no discernible wound, and vanishes after hitting or missing.")
add("Volcanic Boots", "Wondrous Item", "Rare", 1, "Heavy volcanic stone boots that fit your feet and feel light and warm. You have Resistance to Fire damage. They have 10 charges and regain 1d6 + 4 at dawn. When you walk at least 5 ft on solid ground, spend charges as part of that movement. For each, choose an unoccupied space you passed through. A 5 ft Cube there turns volcanic and hot for 1 minute. A creature other than you that enters or starts its turn in one makes a DC 15 Dexterity save or takes 2d6 Fire damage. The Cubes revert if you are Unconscious, or early as a Bonus Action.", fx={"res": ["Fire"]}, ch=[10, "1d6+4", "dawn"])
add("Volt Gauntlets", "Wondrous Item", "Rare", 0, "Metal gauntlets with sharp knuckle points and insulated lining. Your fist Unarmed Strikes deal Piercing damage instead of Bludgeoning. They have 6 charges and regain 1d6 at dawn. With at least 1 charge, they give off sparks. When you hit with a fist Unarmed Strike, spend 1 charge for an extra 1d8 Lightning damage. The target also makes a DC 15 Constitution save or cannot make Opportunity Attacks until the start of its next turn.", ch=[6, "1d6", "dawn"])
add("Voltedge", "Weapon", "Rare", 1, "A split sword with electricity arcing between the halves. It deals an extra 1d6 Lightning damage on a hit. As a Magic action, fire a beam in a 60 ft long, 5 ft wide Line. Each creature in it makes a DC 15 Dexterity save and takes 4d6 Lightning damage on a failure, or half on a success. Usable again after the next dawn.", ch=[1, "1", "dawn"])
add("Vox Helm", "Wondrous Item", "Common", 0, "A metal helm with a second guard over the mouth. With the guard down, your voice sounds obviously enchanted. You can change its pitch, masculinity or femininity, and echo at will with no action.")
add("Wand of Whispers", "Wand", "Rare", 1, "A wax and iron wand shaped like a candle on a candlestick, with a harmless flame that looks like candlelight. The flame sheds Bright Light in a 5 ft radius and Dim Light for 5 ft more. A Bonus Action lights or extinguishes it. It has 7 charges and regains 1d6 + 1 at dusk. Cast Message from it, or spend 3 charges for Sending. When you cast a level 0 to 5 spell while holding it, spend 1 charge per slot level to ignore its Verbal components. If you spend the last charge, roll 1d20. On a 1, the flame dies and it becomes a nonmagical candle and candlestick.", by="a spellcaster", ch=[7, "1d6+1", "dusk"])
add("War Standard of Battlecries", "Wondrous Item", "Very Rare", 1, "A battle standard that stands 10 ft tall and folds to 2 ft. Extend it as a Magic action, then hold it up or plant it in an unoccupied space, and retrieve it by entering its space. While extended, you and allies within 15 ft of it at the start of combat gain +3 to Initiative. It has 4 charges and regains 1d4 at dawn. Within 15 ft of it, spend 1 charge and shout \"Charge!\" to Dash as a Bonus Action. Allies within 15 ft can Dash as a Bonus Action on their next turn. Change the emblem over 1 hour, even during a Short Rest.", ch=[4, "1d4", "dawn"])
add("Warmind Wand", "Wand", "Rare", 1, "A wand made from a warband leader's hilt and jawbone. It has 7 charges and regains 1d6 + 1 at dawn. If you spend the last charge, roll 1d20. On a 1, it becomes a nonmagical sword hilt. **Forced Endurance.** Reaction, 2 charges: an ally within 30 ft who sees or hears you and is dropped to 0 Hit Points (not killed outright) drops to 1 instead. A creature can benefit once per Long Rest. **Form Ranks.** Magic action, 1 charge: an ally who sees or hears you gains 2d4 + 2 Temporary Hit Points and can use its Reaction to move half its Speed without provoking Opportunity Attacks. **Unyielding Critical.** Reaction, 1 charge: when an ally within 30 ft who sees or hears you scores a Critical Hit, add 2d4 to its damage roll. **Warband Strike.** When you take the Attack action, replace one attack and spend 1 charge. A willing creature who sees or hears you uses its Reaction to make one weapon or Unarmed Strike attack.", by="an Orc", ch=[7, "1d6+1", "dawn"])
add("Wavebender's Leiomano", "Weapon", "Rare", 0, "A long oar edged with shark teeth. You gain a +1 bonus to attack and damage rolls. You can cast Control Water (only redirect flow) from it once until the next dawn, and it ends early if you let go. Rowing a waterborne vehicle with it adds 5 ft Speed (1/2 mile per hour) for each such oar used.", fx={"atk": 1, "dmg": 1}, base=["Glaive"], ch=[1, "1", "dawn"])
add("Weapon of Mooring", "Weapon", "Rare", 1, "A dense iron Battleaxe, Longsword or Warhammer with the Heavy property. You gain a +1 bonus to attack and damage rolls. A Large or smaller creature you hit has its Speed reduced by 5 ft until the end of its next turn.", fx={"atk": 1, "dmg": 1})
add("Weapon of Showmanship", "Weapon", "Common", 0, "Any Simple or Martial weapon. When you reduce a Small or larger creature to 0 Hit Points, or score a Critical Hit, you can create a harmless sensory effect or illusion as in Prestidigitation, on the target or nearby.")
add("Weapon of Spite", "Weapon", "Uncommon", 1, "A deep red Melee weapon made by a vengeful smith. You gain a +1 bonus to attack and damage rolls. Against a creature that has damaged you since the end of your last turn, the bonus is +2.", fx={"atk": 1, "dmg": 1})
add("Webgrip Rucksack", "Wondrous Item", "Common", 0, "A spiderskin bag with lifeless eyes that sometimes blink and a thin lining of sticky web. Items inside stay put, and other creatures have Disadvantage on Dexterity (Sleight of Hand) checks to steal from it while you wear it. Its eight straps stick to surfaces like your torso or a tavern wall. While worn, release them as a Magic action. Others have Disadvantage on Strength checks to wrench it from you. It holds 8 cubic feet or 80 lb and stretches a little to fit its contents.")
add("Wildman's Spinning Cleaver", "Weapon", "Very Rare", 1, "A Handaxe that channels bloodlust. You gain a +2 bonus to attack and damage rolls. After a ranged attack, hit or miss, it flies back to your hand. Once per turn when you make a ranged attack with it while Raging, make a second ranged attack as part of it against a different target within 10 ft of the first, even beyond long range, treated as the first target's range. It flies back after the second.", fx={"atk": 2, "dmg": 2}, base=["Handaxe"], by="a Barbarian")
add("Windrazor", "Weapon", "Legendary", 1, "A Longsword with +2 to attack and damage rolls and the Finesse property. It has 10 charges and regains 1d6 + 4 at dawn. Cast with save DC 17 and +5 spell attack: Heroism (1) or Wind Wall (3). **Air Rend.** When you take the Attack action, replace one or more attacks, spending 1 charge each. Each is a special ranged attack against a target within 30 ft. **Sudden Storm.** As a Reaction when a creature within 5 ft damages you, spend 1 charge to make a melee attack with the sword against it. As a Reaction when a creature hits you with a ranged attack, spend 1 charge to cut the projectile and lower the total damage by 1d10 + 5. At 0 damage, a nonmagical projectile is destroyed.", fx={"atk": 2, "dmg": 2}, base=["Longsword"], ch=[10, "1d6+4", "dawn"])
add("Windswept Wyvernplate", "Armor", "Rare", 1, "Half Plate that grows lighter when you inhale. Hold your breath to lighten it and quiet it, which cancels its Disadvantage on Dexterity (Stealth) checks. If you fall while wearing it, hold your breath as a Reaction to cast Feather Fall on yourself.", base=["Half Plate Armor"])
add("Winter's Embrace", "Armor", "Very Rare", 1, "Frosty Breastplate that keeps you at a comfortable temperature. You have Resistance to Cold and Fire damage, and ice or snow Difficult Terrain costs no extra movement. You can cast the level 6 Ice Storm (save DC 16) from it, centered on a point within 5 ft of you, and you are immune to its effects. Usable again after the next dawn.", fx={"res": ["Cold", "Fire"]}, base=["Breastplate"], ch=[1, "1", "dawn"])
add("Wisplight Lantern", "Wondrous Item", "Rare", 0, "A dark Hooded Lantern that needs no fuel and burns with a will-o'-wisp's blue flame. A Bonus Action sets its Bright Light radius from 5 to 20 ft, with Dim Light for the same distance beyond, or closes the hood for no light. It has 4 charges and regains 1d3 + 1 at dusk. As a Magic action, spend 1 charge and touch it to a Large or smaller corpse to see a ghostly illusion replay the last 6 seconds of its conscious life. It shows only the creature's actions, not the cause. It does not work on Undead, and a corpse can be shown once. Alternatively, spend 1 charge with a command word as a Magic action. If any Undead within 60 ft is not behind Cover, the light flashes red.", ch=[4, "1d3+1", "dusk"])
add("Wooden Chain of the Unbroken Circle", "Armor", "Rare", 1, "A Chain Shirt of wooden links enchanted by militant Druids. You gain a bonus to AC equal to your Wisdom modifier (maximum +2). You are trained with it even if you lack Medium armor training.", base=["Chain Shirt"], by="a Druid or Ranger")
add("Wyvernwing", "Weapon", "Rare", 1, "A Greatsword with a wyvern's wing stretched between three folding blades. You gain a +1 bonus to attack and damage rolls. It has 4 charges and regains 1d4 at dawn. As a Magic action, spend 1 charge to fan it open and swing down a buffeting wind in a 15 ft Cone or around you in 5 ft. Each affected creature makes a DC 15 Dexterity save and takes 2d6 Bludgeoning damage and is pushed up to 10 ft on a failure, or half damage on a success. It then folds closed.", fx={"atk": 1, "dmg": 1}, base=["Greatsword"], ch=[4, "1d4", "dawn"])
add("Zafu of the Wandering Mind", "Wondrous Item", "Rare", 1, "A set of stitched meditation pillows. Settling into meditation takes 1 minute. You can talk lightly but cannot move or take actions. While meditating you can levitate yourself and the pillows up to 5 ft. It ends if you take damage, leave the pillows, or choose to stop (no action). Within 100 ft of a pillow, use a Bonus Action and command word to send them into a pocket dimension, and repeat to return them to an open space within 5 ft. The set has 3 charges and regains 1d3 at dawn. While meditating, spend 1 charge to cast Arcane Eye without ending the meditation. If the meditation ends, your Concentration on the spell breaks.", by="a Monk", ch=[3, "1d3", "dawn"])
